-- Ficha de Bartolito y Los Bravos del Son.
--
-- primary_genre corregido de "salsa" a "folklore-son-dominicano"; genres pasa a ["son"].
-- formation_year=1986; occupations ["musician"]; alias "Bartolito y Los Soneros" añadido.

UPDATE artists SET formation_year = 1986, primary_genre = 'folklore-son-dominicano',
       genres = ARRAY['son']::text[], occupations = '["musician"]'::jsonb,
       aliases = ARRAY['Los Bravos del Son','Bartolito','Bartolito y Los Soneros']::text[]
       WHERE slug = 'bartolito-y-los-bravos-del-son';

INSERT INTO editorial_documents (document_type, locale, schema_version, document, status, owner_artist_id, revision)
SELECT 'artist_biography', 'en', 1, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bartolito y Los Bravos del Son is a Dominican son group founded in 1986 in San Felipe de Villa Mella, Santo Domingo Norte, by the singer, guitarist and composer Bartolo del Rosario Chalas —known as Bartolito, born on 24 August 1942 and died on 27 January 2013— who wrote about ninety percent of the songs he recorded."}]},{"type":"paragraph","content":[{"type":"text","text":"From Villa Mella to a first band","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"He grew up in a poor, working family. As a child he listened to the radio songs of the duo «Los Compadres», which his grandparents followed, and it was his grandmother who gave him his first instrument, a guitar. He learned to sing on his own, and Leonardo del Rosario and Jesús Minier, known as “Cundengo”, taught him to play. He started as a professional in the «Sexteto Juvenil» and then formed the «Orquesta Anacruza», which did not last, after which he went back to cutting firewood in San Felipe before founding Los Bravos del Son on 25 August 1986."}]},{"type":"paragraph","content":[{"type":"text","text":"«Villa Mella Querida» and the records","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"In 1987 the producer Ramón Pión, of «Bandera Récords», saw him sing on television and offered to record him. The result was «Villa Mella Querida», which includes «Candela», his own tribute to the April 1965 civil war; his payment was 500 cassettes to sell, and he split the proceeds equally among his musicians. His second album, «Soneando de Verdad», was recorded for «Ringo Récords», owned by Ivelise García, and includes a song named for the producer Domingo del Carmen, who had helped him in his lean years. He later released «Quiéreme», «Abuelita» and «Pajarito Cantor» under the name «Bartolito y Los Soneros». Among his best-known songs are «Ven Vecinita», «Suave Compay», «Sonera», «Que Lindo es el Amor», «Domingo del Carmen» and «Baila mi Rumba»."}]},{"type":"paragraph","content":[{"type":"text","text":"«FestiSON» and the son circuit","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The group played a relevant role in the Festival Caribeño del Son, «FestiSON», over its seven editions from the late 1990s, a festival that brought to Santo Domingo and Santiago acts such as the «Vieja Trova Santiaguera», Adalberto Álvarez, Compay Segundo, Chucho Valdés, «Habana All Star» and the «Orquesta Aragón». The 2002 edition, with Compay Segundo, filled the main hall of the Teatro Nacional, where Bartolito y Los Bravos del Son shared the bill with the «Grupo Maniel» of César Nanúm and the «Soneros de Haina». Day to day the group worked the capital’s son venues, among them the «Monumento del Son», «La Vieja Habana», the «Club Arroyo Hondo», «Villa Con» at the «Secreto Musical», Ciudad Nueva and the «Club 60»."}]},{"type":"paragraph","content":[{"type":"text","text":"Legacy","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"According to a Discogs biography, Bartolito stepped back from the stage from late 2002 and Acroarte honored his career on 12 February 2008. He died at dawn on Sunday, 27 January 2013, and was buried the next day in the Municipal Cemetery of Villa Mella, where the community sang him a last son; the press remembered him as a “poeta sonero”. His albums remain available on streaming platforms, where «Soneando de Verdad» was reissued digitally in September 2025."}]}]}'::jsonb, 'published', id, 1 FROM artists WHERE slug = 'bartolito-y-los-bravos-del-son'
ON CONFLICT (document_type, owner_artist_id, locale) WHERE document_type = 'artist_biography' DO UPDATE
   SET document = excluded.document, status = 'published', revision = editorial_documents.revision + 1, updated_at = now();
DELETE FROM editorial_entity_references WHERE editorial_document_id IN
  (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id
    WHERE a.slug = 'bartolito-y-los-bravos-del-son' AND d.locale = 'en' AND d.document_type = 'artist_biography');
UPDATE artists SET bio_en = 'Bartolito y Los Bravos del Son is a Dominican son group founded in 1986 in San Felipe de Villa Mella, Santo Domingo Norte, by the singer, guitarist and composer Bartolo del Rosario Chalas —known as Bartolito, born on 24 August 1942 and died on 27 January 2013— who wrote about ninety percent of the songs he recorded.

**From Villa Mella to a first band**

He grew up in a poor, working family. As a child he listened to the radio songs of the duo «Los Compadres», which his grandparents followed, and it was his grandmother who gave him his first instrument, a guitar. He learned to sing on his own, and Leonardo del Rosario and Jesús Minier, known as “Cundengo”, taught him to play. He started as a professional in the «Sexteto Juvenil» and then formed the «Orquesta Anacruza», which did not last, after which he went back to cutting firewood in San Felipe before founding Los Bravos del Son on 25 August 1986.

**«Villa Mella Querida» and the records**

In 1987 the producer Ramón Pión, of «Bandera Récords», saw him sing on television and offered to record him. The result was «Villa Mella Querida», which includes «Candela», his own tribute to the April 1965 civil war; his payment was 500 cassettes to sell, and he split the proceeds equally among his musicians. His second album, «Soneando de Verdad», was recorded for «Ringo Récords», owned by Ivelise García, and includes a song named for the producer Domingo del Carmen, who had helped him in his lean years. He later released «Quiéreme», «Abuelita» and «Pajarito Cantor» under the name «Bartolito y Los Soneros». Among his best-known songs are «Ven Vecinita», «Suave Compay», «Sonera», «Que Lindo es el Amor», «Domingo del Carmen» and «Baila mi Rumba».

**«FestiSON» and the son circuit**

The group played a relevant role in the Festival Caribeño del Son, «FestiSON», over its seven editions from the late 1990s, a festival that brought to Santo Domingo and Santiago acts such as the «Vieja Trova Santiaguera», Adalberto Álvarez, Compay Segundo, Chucho Valdés, «Habana All Star» and the «Orquesta Aragón». The 2002 edition, with Compay Segundo, filled the main hall of the Teatro Nacional, where Bartolito y Los Bravos del Son shared the bill with the «Grupo Maniel» of César Nanúm and the «Soneros de Haina». Day to day the group worked the capital’s son venues, among them the «Monumento del Son», «La Vieja Habana», the «Club Arroyo Hondo», «Villa Con» at the «Secreto Musical», Ciudad Nueva and the «Club 60».

**Legacy**

According to a Discogs biography, Bartolito stepped back from the stage from late 2002 and Acroarte honored his career on 12 February 2008. He died at dawn on Sunday, 27 January 2013, and was buried the next day in the Municipal Cemetery of Villa Mella, where the community sang him a last son; the press remembered him as a “poeta sonero”. His albums remain available on streaming platforms, where «Soneando de Verdad» was reissued digitally in September 2025.' WHERE slug = 'bartolito-y-los-bravos-del-son';

